input.content:
const fs = require('fs');
const path = require('path');
const htmlPath = path.join(__dirname, '..', 'index.html');
const html = fs.readFileSync(htmlPath, 'utf8');

const scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
if (!scriptMatch) throw new Error('No <script> found');
const scriptSrc = scriptMatch[1];

// Mock DOM
const classList = { removed: new Set(), added: new Set(), remove(c){ this.removed.add(c); }, add(c){ this.added.add(c); } };
const foodIcon = { _html: '', set innerHTML(v){ this._html = v; }, get innerHTML(){ return this._html; } };
const foodName = { _text: '', set textContent(v){ this._text = v; }, get textContent(){ return this._text; } };
const display = { classList };
const listeners = {};
const document = {
  addEventListener(ev, fn){ listeners[ev] = fn; },
  getElementById(id){ return { addEventListener(ev, fn){ this['on'+ev] = fn; } }; },
  querySelector(sel){
    if (sel === '.food-icon') return foodIcon;
    if (sel === '.food-name') return foodName;
    if (sel === '.lunch-display') return display;
  }
};

// Mock timers: we capture scheduled callbacks and can run them manually
let scheduled = [];
let nextId = 1;
global.setTimeout = (fn, ms) => { const id = nextId++; scheduled.push({ id, fn, ms, cancelled: false }); return id; };
global.clearTimeout = (id) => { const t = scheduled.find(s => s.id === id); if (t) t.cancelled = true; };

const ctx = { document };
const fn = new Function('document', scriptSrc);
fn(document);

// Simulate DOMContentLoaded
listeners['DOMContentLoaded']();

// capture the generate button click handler by getting generateBtn
const generateBtn = {
  _handler: null,
  addEventListener(ev, fn){ this._handler = fn; }
};
global.document = { addEventListener(ev, fn){ if(ev==='DOMContentLoaded') fn(); }, getElementById(id){ if(id==='generateBtn') return generateBtn; }, querySelector(sel){
  if (sel === '.food-icon') return foodIcon;
  if (sel === '.food-name') return foodName;
  if (sel === '.lunch-display') return display;
} };
// Re-run with click handler capture
let btnHandler = null;
function run(handlerCapture){
  const d = {
    addEventListener(ev, fn){ if(ev === 'DOMContentLoaded') fn(); },
    getElementById(id){ if(id === 'generateBtn') return { addEventListener(ev, fn){ handlerCapture = fn; } }; },
    querySelector(sel){
      if (sel === '.food-icon') return foodIcon;
      if (sel === '.food-name') return foodName;
      if (sel === '.lunch-display') return display;
    }
  };
  new Function('document', scriptSrc)(d);
  return handlerCapture;
}

// 1. Validate lunchMenu references from source
const menuBlock = scriptSrc.match(/const lunchMenu = (\[[\s\S]*?\]);/)[1];
const menu = eval(menuBlock);
console.log('=== TEST 1: lunchMenu completeness ===');
console.log('entries:', menu.length);
const missing = menu.filter(e => !e.svg || !e.alt || !e.name);
console.log('entries missing name/svg/alt:', missing.length ? JSON.stringify(missing) : 'none');
const filesMissing = [];
for (const e of menu) {
  const p = path.join(__dirname, '..', 'svg', path.basename(e.svg));
  if (!fs.existsSync(p)) filesMissing.push(e.svg);
}
console.log('referenced svg files missing on disk:', filesMissing.length ? filesMissing.join(', ') : 'none');
const faIndex = menu.filter(e => /^fas\b/.test(e.svg || '') || /fa-/.test(e.svg || ''));
console.log('entries still using Font Awesome classes:', faIndex.length ? JSON.stringify(faIndex) : 'none');
console.log('all have alt text:', menu.every(e => typeof e.alt === 'string' && e.alt.length > 0));

// 2. Test timer cancellation: click twice quickly, first timer must NOT fire
console.log('\n=== TEST 2: repeated-click timer cancellation ===');
scheduled = [];
global.document = document;
const handler = new Function('document', scriptSrc);
// Use our own run capture
let clickHandler;
const doc2 = {
  addEventListener(ev, fn){ if(ev === 'DOMContentLoaded') fn(); },
  getElementById(id){ if(id === 'generateBtn') return { addEventListener(ev, fn){ clickHandler = fn; } }; },
  querySelector(sel){
    if (sel === '.food-icon') return foodIcon;
    if (sel === '.food-name') return foodName;
    if (sel === '.lunch-display') return display;
  }
};
new Function('document', scriptSrc)(doc2);

// Page-load call already scheduled one timer
scheduled = []; // clear
clickHandler(); // click 1
const timerAfterClick1 = scheduled.length;
console.log('timers scheduled after click 1:', timerAfterClick1);
clickHandler(); // click 2 (rapid second click)
const timerAfterClick2 = scheduled.length;
console.log('timers scheduled after click 2:', timerAfterClick2 - timerAfterClick1, '(should be 1 new; previous cancelled)');
const cancelled = scheduled.filter(t => t.cancelled);
const pending = scheduled.filter(t => !t.cancelled);
console.log('cancelled timers:', cancelled.length);
console.log('pending active timers:', pending.length, '(should be exactly 1)');

// Run the single pending timer
pending[0].fn();
console.log('final result shown:', foodName._text);
console.log('final img html:', foodIcon._html);
const imgMatch = foodIcon._html.match(/src="([^"]+)"\s+alt="([^"]+)"/);
console.log('img uses local svg:', imgMatch ? imgMatch[1] : 'NO');
console.log('img has alt text:', imgMatch ? imgMatch[2] : 'NO, MISSING');

// 3. Verify no external URLs, emoji, FA classes in sources rendered
console.log('\n=== TEST 3: no external images / no FA food icons in menu ===');
const extUrls = menu.filter(e => /^https?:\/\//.test(e.svg));
console.log('entries using external URLs:', extUrls.length ? mapToString(extUrls) : 'none');
const emoji = menu.filter(e => /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test((e.name + e.svg + e.alt)));
console.log('entries containing emoji:', emoji.length ? mapToString(emoji) : 'none');

function mapToString(arr){ return arr.map(e => e.name).join(', '); }

console.log('\n=== ALL TESTS COMPLETE ===');

const fs = require('fs');
const path = require('path');
const htmlPath = path.join(__dirname, '..', 'RecSys-LLMs', 'week1', 'index.html');
const html = fs.readFileSync(htmlPath, 'utf8');
const scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
if (!scriptMatch) throw new Error('No <script> found');
const scriptSrc = scriptMatch[1];

async function main() {
  // ---- TEST 1: lunchMenu integrity ----
  const menuBlock = scriptSrc.match(/const lunchMenu = (\[[\s\S]*?\]);/s)[1];
  const menu = Function('return ' + menuBlock)();
  console.log('=== TEST 1: lunchMenu completeness ===');
  console.log('entries:', menu.length);
  const incomplete = menu.filter(e => !e.name || !e.svg || !e.alt);
  console.log('entries missing name/svg/alt:', incomplete.length ? JSON.stringify(incomplete) : 'none');
  const filesMissing = menu.filter(e => !fs.existsSync(path.join(__dirname, '..', 'RecSys-LLMs', 'week1', e.svg)));
  console.log('referenced svg files missing on disk:', filesMissing.length ? filesMissing.map(e => e.svg).join(', ') : 'none');
  const faLeft = menu.filter(e => /\bfas\b|fa-[a-z]/.test(e.svg));
  console.log('entries still using Font Awesome classes:', faLeft.length ? JSON.stringify(faLeft) : 'none');
  console.log('all entries have alt text:', menu.every(e => typeof e.alt === 'string' && e.alt.length > 0));

  // fixtures for DOM + timers
  const makeMocks = () => {
    const classList = { remove() {}, add() {} };
    const foodIcon = { innerHTML: '' };
    const foodName = { textContent: '' };
    const lunchDisplay = { classList };
    let clickHandler = null;
    const document = {
      addEventListener(ev, fn) { if (ev === 'DOMContentLoaded') fn(); },
      getElementById(id) { if (id === 'generateBtn') return { addEventListener(ev, fn) { if (ev === 'click') clickHandler = fn; } }; },
      querySelector(sel) {
        if (sel === '.food-icon') return foodIcon;
        if (sel === '.food-name') return foodName;
        if (sel === '.lunch-display') return lunchDisplay;
      }
    };
    return { document, get clickHandler() { return clickHandler; }, foodIcon, foodName, lunchDisplay };
  };

  const timers = [];
  let nextId = 1;
  const realSetTimeout = setTimeout;
  const mockTimers = {
    setTimeout(fn, ms) { const id = nextId++; timers.push({ id, fn, ms, cancelled: false }); return id; },
    clearTimeout(id) { const t = timers.find(t => t.id === id); if (t) t.cancelled = true; }
  };

  // ---- TEST 2: repeated-click timer cancellation ----
  console.log('\n=== TEST 2: repeated-click timer cancellation ===');
  timers.length = 0;
  const m = makeMocks();
  // run script with mocked globals
  const sandbox = {
    document: m.document,
    setTimeout: mockTimers.setTimeout,
    clearTimeout: mockTimers.clearTimeout,
    Math,
    console
  };
  new Function('document', 'setTimeout', 'clearTimeout', 'Math', 'console', scriptSrc)(
    m.document, mockTimers.setTimeout, mockTimers.clearTimeout, Math, console
  );
  const activeAfterLoad = timers.filter(t => !t.cancelled);
  console.log('active timer after page-load call fire:', activeAfterLoad.length);
  activeAfterLoad[0].fn(); // let the page-load initial result complete (random)

  timers.length = 0;
  m.clickHandler(); // click 1
  const t1 = timers.filter(t => !t.cancelled);
  console.log('active timers after click 1:', t1.length, '(expected 1)');
  m.clickHandler(); // click 2 quickly (before 500ms)
  const t2 = timers.filter(t => !t.cancelled);
  const cancelled = timers.filter(t => t.cancelled);
  console.log('active timers after click 2:', t2.length, '(expected exactly 1)');
  console.log('click-1 timer cancelled:', cancelled.length, '(expected 1)');

  // deterministic: force random, then run the surviving timer
  let forcedIndex = 0;
  const origRandom = Math.random;
  Math.random = () => 0; // force index 0
  const m2 = makeMocks();
  timers.length = 0;
  new Function('document', 'setTimeout', 'clearTimeout', 'Math', 'console', scriptSrc)(
    m2.document, mockTimers.setTimeout, mockTimers.clearTimeout, Math, console
  );
  timers.length = 0;
  m2.clickHandler();
  m2.clickHandler();
  const surviving = timers.filter(t => !t.cancelled);
  surviving[0].fn();
  console.log('final displayed name:', m2.foodName.textContent);
  console.log('final icon html:', m2.foodIcon.innerHTML);
  const imgOk = /^<img class="dish-image" src="svg\/[a-z-]+\.svg" alt="[^"]+">$/.test(m2.foodIcon.innerHTML);
  console.log('result is <img> with src=svg/*.svg and alt=...:', imgOk);
  Math.random = origRandom;

  // ---- TEST 3: rapid-click simulation - only last click's result can appear ----
  console.log('\n=== TEST 3: rapid triple-click, only the last pending timer survives ===');
  Math.random = () => 0.99; // last element
  const m3 = makeMocks();
  timers.length = 0;
  new Function('document', 'setTimeout', 'clearTimeout', 'Math', 'console', scriptSrc)(
    m3.document, mockTimers.setTimeout, mockTimers.clearTimeout, Math, console
  );
  timers.length = 0;
  m3.clickHandler();
  m3.clickHandler();
  m3.clickHandler();
  const active = timers.filter(t => !t.cancelled);
  const canc = timers.filter(t => t.cancelled);
  console.log('active timers after 3 rapid clicks:', active.length, '(expected 1)');
  console.log('cancelled timers:', canc.length, '(expected 2)');
  active[0].fn();
  console.log('final displayed name:', m3.foodName.textContent, '(expected BBQ)');
  Math.random = origRandom;

  console.log('\n===ALL TESTS COMPLETE===');
}

main().catch(e => { console.error(e); process.exit(1); });

