foreach ($f in $files) {
  $head = Get-Content $f.FullName -TotalCount 3 -ErrorAction SilentlyContinue
  $joined = ($head -join ' ')
  $isXml = $joined -match '<\?xml' -or $joined -match '<svg'
  $isHtml = $joined -match '<html' -or $joined -match '<!DOCTYPE html'
  $hasPath = ($joined -match '<path') -or ($joined -match '<circle')
  $status = if ($isHtml) { 'HTML ERROR PAGE' } elseif ($isXml -and $hasPath) { 'VALID SVG' } elseif ($isXml) { 'XML BUT NO SHAPES?' } else { 'NOT SVG XML' }
  Write-Output ("{0,-14} {1,6} bytes  [{2}]  {3}" -f $f.Name, $f.Length, $status, ($head -join ' | ').Substring(0, [Math]::Min(80, ($head -join ' ').Length)))
}

