const puppeteer = require('puppeteer-core');
const path = require('path');

const INDEX = 'C:\\Users\\dmitr\\Desktop\\dz_jin\\RecSys-LLMs\\week1\\index.html';
const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME,
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  const consoleErrors = [];
  const pageErrors = [];
  page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  page.on('pageerror', err => pageErrors.push(String(err)));

  await page.goto('file:///' + INDEX.replace(/\\/g, '/'), { waitUntil: 'load', timeout: 30000 });
  // let internet load + initial auto-selection (500ms timer) finish
  await sleep(1200);

  // Install a mutation recorder in the page
  await page.evaluate(() => {
    window.__observed = { names: [], icons: [] };
    const rec = (list, el, store) => el.addEventListener('DOMCharacterDataModified', e => {
      const v = e.target.nodeValue;
      if (v && v !== 'Thinking...') store.push(v);
    });
    const nm = document.querySelector('.food-name');
    const ic = document.querySelector('.food-icon');
    // We record via MutationObserver on innerHTML change of food-icon and text change of food-name
    new MutationObserver(muts => {
      for (const m of muts) {
        if (m.type === 'characterData') {
          const v = m.target.nodeValue;
          if (v && v !== 'Thinking...') window.__observed.names.push(v);
        }
      }
    }).observe(nm, { characterData: true, childList: true, subtree: true });
    new MutationObserver(muts => {
      for (const m of muts) {
        if (m.type === 'childList') {
          const img = ic.querySelector('img');
          if (img) window.__observed.icons.push(img.getAttribute('src') + ' |alt=' + img.getAttribute('alt'));
        }
      }
    }).observe(ic, { childList: true, subtree: true, characterData: true });
  });

  // ---- TEST 1: two clicks, Pizza then BBQ (100 ms apart) ----
  console.log('=== TEST 1 ===');
  await page.evaluate(() => {
    // current state after page-load auto select
    window.__t1 = { name: document.querySelector('.food-name').textContent, icon: document.querySelector('.food-icon').innerHTML };
    window.__observed.names.length = 0;
    window.__observed.icons.length = 0;
    // click 1 -> Pizza (index 0)
    Math.random = () => 0;
    document.getElementById('generateBtn').click();
    const nAfter1 = document.querySelector('.food-name').textContent;
    // 100 ms later click 2 -> BBQ (index 11)
    window.__t1Names = [nAfter1];
    setTimeout(() => {
      Math.random = () => 0.999;
      document.getElementById('generateBtn').click();
      window.__t1Names.push(document.querySelector('.food-name').textContent);
    }, 100);
  });
  await sleep(900); // 100 + 500 + margin

  const t1 = await page.evaluate(() => ({
    immStart: window.__t1.name,
    namesAfterEachClick: window.__t1Names,
    observedNames: window.__observed.names.slice(),
    observedIcons: window.__observed.icons.slice(),
    finalName: document.querySelector('.food-name').textContent,
    finalIcon: document.querySelector('.food-icon').innerHTML
  }));
  console.log('immediate name before clicks:', JSON.stringify(t1.immStart));
  console.log('name right after click1 (wasitPizza or Thinking):', JSON.stringify(t1.namesAfterEachClick));
  console.log('all non-Thinking dish-name changes observed:', JSON.stringify(t1.observedNames));
  console.log('all icon changes observed:', JSON.stringify(t1.observedIcons));
  console.log('final name:', JSON.stringify(t1.finalName), 'expected "BBQ"');
  console.log('final icon:', JSON.stringify(t1.finalIcon));

  // ---- TEST 2: 10 clicks spaced 25ms, known item sequence ----
  console.log('\n=== TEST 2 ===');
  await page.evaluate(() => {
    window.__observed.names.length = 0;
    window.__observed.icons.length = 0;
    const seq = [0.05, 0.15, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 0.85, 0.999];
    // floors: 0(Pizza),1(Sushi),3(Salad),4(Tacos),5(Ramen),6(Sandwich),7(Pasta),9(Steak),10(Soup),11(BBQ)
    let i = 0;
    Math.random = () => seq[Math.min(i++, seq.length - 1)];
    const btn = document.getElementById('generateBtn');
    let gap = 0;
    (function tick() {
      if (i <= seq.length) {
        btn.click();
        if (i < seq.length) {
          setTimeout(tick, 25);
        }
      }
    })();
  });
  await sleep(1200); // 10*25 + 500 + margin

  const t2 = await page.evaluate(() => ({
    observedNames: window.__observed.names.slice(),
    observedIcons: window.__observed.icons.slice(),
    finalName: document.querySelector('.food-name').textContent,
    finalIcon: document.querySelector('.food-icon').innerHTML
  }));
  console.log('all non-Thinking dish-name changes observed:', JSON.stringify(t2.observedNames));
  console.log('all icon changes observed:', JSON.stringify(t2.observedIcons));
  console.log('final name:', JSON.stringify(t2.finalName), 'expected "BBQ"');
  console.log('final icon:', JSON.stringify(t2.finalIcon));

  console.log('\n--- diagnostics ---');
  console.log('console errors:', consoleErrors.length ? JSON.stringify(consoleErrors) : 'NONE');
  console.log('page JS errors:', pageErrors.length ? JSON.stringify(pageErrors) : 'NONE');

  await browser.close();
})().catch(e => { console.error('FATAL:', e); process.exit(1); });

