const INDEX = 'C:\\Users\\dmitr\\Desktop\\dz_jin\\RecSys-LLMs\\week1\\index.html';
const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME, headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  const consoleErrors = [];
  const pageErrors = [];
  page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  page.on('pageerror', err => pageErrors.push(String(err)));

  await page.goto('file:///' + INDEX.replace(/\\/g, '/'), { waitUntil: 'load', timeout: 30000 });
  await sleep(1200); // let page-load auto-selection (500ms) finish

  // Robust snapshot recorder: records every change of .food-name text AND every img rendered in .food-icon
  await page.evaluate(() => {
    window.__log = [];
    const stamp = (kind, v) => window.__log.push({ t: Date.now(), kind, v });
    const nm = document.querySelector('.food-name');
    const ic = document.querySelector('.food-icon');
    const snapshotName = () => nm.textContent;
    const snapshotIconImg = () => {
      const img = ic.querySelector('img');
      return img ? img.getAttribute('src') + ' |alt=' + img.getAttribute('alt') : ic.innerHTML;
    };
    const prev = { name: snapshotName(), icon: snapshotIconImg() };
    stamp('INIT-name', prev.name); stamp('INIT-icon', prev.icon);
    // poll every 5 ms and log diffs (no production code touched)
    window.__poll = setInterval(() => {
      const n = snapshotName();
      const i = snapshotIconImg();
      if (n !== prev.name) { prev.name = n; stamp('name', n); }
      if (i !== prev.icon) { prev.icon = i; stamp('icon', i); }
    }, 5);
  });

  // ---------- TEST 1 ----------
  console.log('=== TEST 1: click1=Pizza(ind 0), 100ms later click2=BBQ(ind 11) ===');
  await page.evaluate(() => {
    window.__log.length = 0;
    // click 1 -> Pizza
    Math.random = () => 0;
    document.getElementById('generateBtn').click();
    setTimeout(() => {
      // 100 ms later click 2 -> BBQ
      Math.random = () => 0.999;
      document.getElementById('generateBtn').click();
    }, 100);
  });
  await sleep(900); // 100 + 500 + margin
  const t1 = await page.evaluate(() => ({
    log: window.__log.slice(),
    finalName: document.querySelector('.food-name').textContent,
    finalIcon: document.querySelector('.food-icon').innerHTML
  }));
  console.log('event timeline:');
  for (const e of t1.log) console.log('  +' + ((Date.now() - (0)) - 0) + ' ' + e.kind + ' = ' + JSON.stringify(e.v).slice(0, 80));
  // Simplify: print in order
  for (const e of t1.log) console.log('  [' + e.kind + '] ' + JSON.stringify(e.v).slice(0, 80));
  const names1 = t1.log.filter(e => e.kind === 'name').map(e => e.v);
  const icons1 = t1.log.filter(e => e.kind === 'icon').map(e => e.v);
  const pizzaShown = names1.includes('Pizza');
  const bbqFinal = t1.finalName === 'BBQ' && /svg\/bbq\.svg/.test(t1.finalIcon) && /alt=A BBQ grill/.test(t1.finalIcon);
  console.log('name states observed:', JSON.stringify(names1));
  console.log('icon states observed:', JSON.stringify(icons1));
  console.log('Pizza ever displayed after its timed-out click?', pizzaShown);
  console.log('final = BBQ with svg/bbq.svg + alt "A BBQ grill"?', bbqFinal);

  // ---------- TEST 2 ----------
  console.log('\n=== TEST 2: 10 clicks, 25ms apart, known menu sequence ===');
  await page.evaluate(() => {
    window.__log.length = 0;
    // expected selected item indices: 0(Pizza),1(Sushi),3(Salad),4(Tacos),5(Ramen),6(Sandwich),7(Pasta),9(Steak),10(Soup),11(BBQ)
    const seq = [0.05, 0.15, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 0.85, 0.999];
    let i = 0;
    Math.random = () => seq[Math.min(i++, seq.length - 1)];
    const btn = document.getElementById('generateBtn');
    (function tick() {
      btn.click();
      if (i < seq.length) setTimeout(tick, 25);
    })();
  });
  await sleep(1300); // 10*25 + 500 + margin
  const t2 = await page.evaluate(() => ({
    log: window.__log.slice(),
    finalName: document.querySelector('.food-name').textContent,
    finalIcon: document.querySelector('.food-icon').innerHTML
  }));
  for (const e of t2.log) console.log('  [' + e.kind + '] ' + JSON.stringify(e.v).slice(0, 80));
  const names2 = t2.log.filter(e => e.kind === 'name').map(e => e.v);
  const icons2 = t2.log.filter(e => e.kind === 'icon').map(e => e.v);
  const intermediateShown = names2.filter(n => n !== 'Thinking...' && n !== t2.finalName);
  const final2 = t2.finalName === 'BBQ' && /svg\/bbq\.svg/.test(t2.finalIcon) && /alt=A BBQ grill/.test(t2.finalIcon);
  console.log('name states observed:', JSON.stringify(names2));
  console.log('icon states observed:', JSON.stringify(icons2));
  console.log('any intermediate dish displayed (not Thinking, not final)?', intermediateShown.length ? JSON.stringify(intermediateShown) : 'NO');
  console.log('final = BBQ with svg/bbq.svg + alt "A BBQ grill"?', final2);

  console.log('\n--- diagnostics ---');
  console.log('console errors:', consoleErrors.length ? JSON.stringify(consoleErrors) : 'NONE');
  console.log('page JS errors:', pageErrors.length ? JSON.stringify(pageErrors) : 'NONE');

  await browser.close();
})().catch(e => { console.error('FATAL:', e); process.exit(1); });
